#!/usr/bin/env python3
"""Final verification pass."""
import json
import sys
from concurrent.futures import ThreadPoolExecutor, as_completed
from netmiko import ConnectHandler

VYOS = {
    "HQ-Edge": {"host": "192.168.122.11", "device_type": "vyos", "username": "vyos", "password": "test"},
    "Hub-A":   {"host": "192.168.122.12", "device_type": "vyos", "username": "vyos", "password": "test"},
    "Hub-B":   {"host": "192.168.122.13", "device_type": "vyos", "username": "vyos", "password": "test"},
}

MIKROTIK = {
    "Branch-1": {"host": "192.168.122.21", "device_type": "mikrotik_routeros", "username": "admin", "password": "test"},
    "Branch-2": {"host": "192.168.122.22", "device_type": "mikrotik_routeros", "username": "admin", "password": "test"},
    "Branch-3": {"host": "192.168.122.23", "device_type": "mikrotik_routeros", "username": "admin", "password": "test"},
    "Branch-4": {"host": "192.168.122.24", "device_type": "mikrotik_routeros", "username": "admin", "password": "test"},
}

HOSTS = {
    "B1-PC1": ("192.168.122.31", "10.1.1.10"),
    "B1-PC2": ("192.168.122.32", "10.1.1.11"),
    "B2-PC1": ("192.168.122.33", "10.1.2.10"),
    "B2-PC2": ("192.168.122.34", "10.1.2.11"),
    "B3-PC1": ("192.168.122.35", "10.1.3.10"),
    "B3-PC2": ("192.168.122.36", "10.1.3.11"),
    "B4-PC1": ("192.168.122.37", "10.2.1.10"),
    "B4-PC2": ("192.168.122.38", "10.2.1.11"),
    "B4-PC3": ("192.168.122.39", "10.2.2.10"),
    "B4-PC4": ("192.168.122.40", "10.2.2.11"),
}

GUEST_HOSTS = {"B4-PC3", "B4-PC4"}
GUEST_ADDRS = {"10.2.2.10", "10.2.2.11"}

def collect_router_vyos(name, params):
    r = {}
    try:
        conn = ConnectHandler(**params)
        r["ospf_neighbor"] = conn.send_command("show ip ospf neighbor", read_timeout=15)
        r["routes"] = conn.send_command("show ip route", read_timeout=15)
        if name == "HQ-Edge":
            r["bgp"] = conn.send_command("show ip bgp", read_timeout=15)
            r["bgp_summary"] = conn.send_command("show ip bgp summary", read_timeout=15)
            r["bgp_adv_a"] = conn.send_command("show ip bgp neighbors 203.0.113.1 advertised-routes", read_timeout=15)
            r["bgp_adv_b"] = conn.send_command("show ip bgp neighbors 203.0.113.5 advertised-routes", read_timeout=15)
            r["nat"] = conn.send_command("show nat source rules", read_timeout=15)
        conn.disconnect()
    except Exception as e:
        r["error"] = str(e)
    return name, r

def collect_router_mt(name, params):
    r = {}
    try:
        conn = ConnectHandler(**params)
        r["ospf_neighbor"] = conn.send_command("/routing ospf neighbor print detail", read_timeout=15)
        r["routes"] = conn.send_command("/ip route print terse", read_timeout=15)
        conn.disconnect()
    except Exception as e:
        r["error"] = str(e)
    return name, r

def ping_from_host(host_name, mgmt_ip, targets):
    """Ping a list of targets from a host. Returns dict of target->success."""
    results = {}
    try:
        conn = ConnectHandler(host=mgmt_ip, device_type="linux", username="root", password="alpine")
        for target in targets:
            out = conn.send_command(f"ping -c 2 -W 2 {target}", read_timeout=15)
            success = "0% packet loss" in out or "bytes from" in out
            results[target] = success
        conn.disconnect()
    except Exception as e:
        results["error"] = str(e)
    return host_name, results

def main():
    all_data = {}

    # Collect router state
    with ThreadPoolExecutor(max_workers=19) as pool:
        futures = []
        for name, params in VYOS.items():
            futures.append(pool.submit(collect_router_vyos, name, params))
        for name, params in MIKROTIK.items():
            futures.append(pool.submit(collect_router_mt, name, params))
        for f in as_completed(futures):
            name, r = f.result()
            all_data[name] = r
            print(f"  router {name} done", file=sys.stderr)

    # Print router state
    for name in ["HQ-Edge", "Hub-A", "Hub-B", "Branch-1", "Branch-2", "Branch-3", "Branch-4"]:
        print(f"\n{'='*60}")
        print(f"{name}")
        print(f"{'='*60}")
        for k, v in all_data[name].items():
            print(f"--- {k} ---")
            print(v)

    # All host lab addresses
    all_host_addrs = {name: addr for name, (_, addr) in HOSTS.items()}
    non_guest_addrs = {n: a for n, a in all_host_addrs.items() if n not in GUEST_HOSTS}
    guest_addrs_map = {n: a for n, a in all_host_addrs.items() if n in GUEST_HOSTS}

    # Ping targets per host
    host_targets = {}
    for host_name, (mgmt_ip, host_addr) in HOSTS.items():
        targets = []
        # Internet targets
        targets.extend(["8.8.8.8", "1.1.1.1"])
        if host_name in GUEST_HOSTS:
            # Guest: ping other guest hosts + all non-guest (should fail)
            for other_name, other_addr in guest_addrs_map.items():
                if other_name != host_name:
                    targets.append(other_addr)
            for other_name, other_addr in non_guest_addrs.items():
                targets.append(other_addr)
        else:
            # Non-guest: ping all other non-guest + all guest (should fail)
            for other_name, other_addr in non_guest_addrs.items():
                if other_name != host_name:
                    targets.append(other_addr)
            for other_name, other_addr in guest_addrs_map.items():
                targets.append(other_addr)
        host_targets[host_name] = targets

    # Run pings in parallel
    ping_results = {}
    with ThreadPoolExecutor(max_workers=10) as pool:
        futures = []
        for host_name, (mgmt_ip, _) in HOSTS.items():
            futures.append(pool.submit(ping_from_host, host_name, mgmt_ip, host_targets[host_name]))
        for f in as_completed(futures):
            name, r = f.result()
            ping_results[name] = r
            print(f"  pings {name} done", file=sys.stderr)

    # Print ping results
    print(f"\n{'='*60}")
    print("PING RESULTS")
    print(f"{'='*60}")

    failures = []
