                    targets.append(other_addr)
            for other_name, other_addr in guest_addrs_map.items():
                targets.append(other_addr)
        host_targets[host_name] = targets

    # Run pings in parallel
    ping_results = {}
    with ThreadPoolExecutor(max_workers=10) as pool:
        futures = []
        for host_name, (mgmt_ip, _) in HOSTS.items():
            futures.append(pool.submit(ping_from_host, host_name, mgmt_ip, host_targets[host_name]))
        for f in as_completed(futures):
            name, r = f.result()
            ping_results[name] = r
            print(f"  pings {name} done", file=sys.stderr)

    # Print ping results
    print(f"\n{'='*60}")
    print("PING RESULTS")
    print(f"{'='*60}")

    failures = []
    expected_failures = []
    for host_name in sorted(ping_results.keys()):
        results = ping_results[host_name]
        is_guest = host_name in GUEST_HOSTS
        host_addr = all_host_addrs[host_name]

        for target, success in sorted(results.items()):
            if target == "error":
                continue
            target_is_guest = target in GUEST_ADDRS
            target_is_internet = target in ("8.8.8.8", "1.1.1.1")

            # Determine if this should succeed
            if target_is_internet:
                should_succeed = True
            elif is_guest and target_is_guest:
                should_succeed = True  # guest-to-guest
            elif is_guest != target_is_guest:
                should_succeed = False  # guest <-> non-guest
            else:
                should_succeed = True  # non-guest to non-guest

            status = "OK" if success == should_succeed else "UNEXPECTED"
            if status == "UNEXPECTED":
                failures.append(f"  {host_name} ({host_addr}) -> {target}: got {'pass' if success else 'fail'}, expected {'pass' if should_succeed else 'fail'}")
            elif not should_succeed:
                expected_failures.append(f"  {host_name} -> {target}: correctly blocked")

    if failures:
        print("\nUNEXPECTED RESULTS:")
        for f in failures:
            print(f)
    else:
        print("\nAll ping tests match expectations!")

    print(f"\nGuest policy blocks verified: {len(expected_failures)} pairs correctly blocked")
    print(f"Total tests run: {sum(len(v) - (1 if 'error' in v else 0) for v in ping_results.values())}")

if __name__ == "__main__":
    main()
